1	import * as THREE from 'three';
2	import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
3	import { CONFIG } from '../../config';
4	
5	/* =====================================================================
6	   HÌNH HỌC NGƯỜI ĐI BỘ — một hình gộp cho mọi kiểu người (spec G5, G8): thân, đầu, tóc, hai tay (bắp tay áo cộc + cẳng tay),
7	   hai chân (đùi + ống quần + giày), nón lá, ba lô. Theo personGeo của bản dựng thử, bớt cạnh để ≤ CONFIG.people.maxVerts đỉnh.
8	   Mét, tỉ lệ 1: cao ≈ 1,65 m (≈ 1,79 m tính chóp nón), mặt hướng +X, rộng theo Z, chân chạm y = 0. Có index, không uv.
9	   Thuộc tính đỉnh (shader ở material.ts đọc):
10	   - aPart: 0 thân/đầu/tóc, 1 chân trái (−Z, vì mặt hướng +X), 2 chân phải (+Z), 3 tay trái, 4 tay phải, 5 nón lá, 6 ba lô (5, 6 bật theo cờ instance)
11	   - aSeg: 0 đoạn trên, 1 đoạn dưới khớp (quay thêm quanh aPivot2); aPivot: cao độ hông / vai; aPivot2: cao độ gối / khuỷu
12	   - aMask: 0 màu cố định aFix, 1 áo (instanceColor), 2 quần (aPants); aFix: màu cố định tuyến tính (da, tóc, giày, nón, ba lô)
13	   ===================================================================== */
14	export const PP_HIP = 0.86, PP_KNEE = 0.46, PP_SHOULDER = 1.37, PP_ELBOW = 1.1;   // m — cao độ khớp ở tỉ lệ 1
15	export enum PpPart { Body = 0, LegL = 1, LegR = 2, ArmL = 3, ArmR = 4, Hat = 5, Pack = 6 }
16	export enum PpMask { Fixed = 0, Shirt = 1, Pants = 2 }
17	
18	const C = CONFIG.people.palette;
19	const cap = (r: number, l: number) => new THREE.CapsuleGeometry(r, l, 2, 6);   // tay chân: 6 cạnh, nắp 2 đoạn
20	
21	/* Gắn thuộc tính khớp và màu cho một bộ phận; bỏ uv để mọi phần gộp được */
22	function ppTag(g: THREE.BufferGeometry, part: PpPart, pivot: number, fix: number, mask: PpMask, seg = 0, pivot2 = 0): THREE.BufferGeometry {
23	  if (g.getAttribute('uv')) g.deleteAttribute('uv'); g.clearGroups();
24	  const n = g.getAttribute('position').count, col = new THREE.Color(fix), F = new Float32Array(n * 3);
25	  for (let i = 0; i < n; i++) { F[i * 3] = col.r; F[i * 3 + 1] = col.g; F[i * 3 + 2] = col.b; }
26	  const fill = (v: number) => new THREE.BufferAttribute(new Float32Array(n).fill(v), 1);
27	  g.setAttribute('aPart', fill(part)); g.setAttribute('aSeg', fill(seg)); g.setAttribute('aPivot', fill(pivot)); g.setAttribute('aPivot2', fill(pivot2));
28	  g.setAttribute('aMask', fill(mask)); g.setAttribute('aFix', new THREE.BufferAttribute(F, 3));
29	  return g;
30	}
31	
32	/* Dựng mới mỗi lần gọi (không cache): bên gọi giữ một bản dùng chung cho mọi hệ người nếu muốn */
33	export function ppBuildGeometry(): THREE.BufferGeometry {
34	  const parts = [
35	    ppTag(cap(0.15, 0.3).scale(0.78, 1, 1.18).translate(0, 1.12, 0), PpPart.Body, 0, C.skin, PpMask.Shirt),                     // thân (áo)
36	    ppTag(new THREE.SphereGeometry(0.115, 8, 6).translate(0, 1.54, 0), PpPart.Body, 0, C.skin, PpMask.Fixed),                    // đầu
37	    ppTag(new THREE.SphereGeometry(0.123, 8, 4, 0, Math.PI * 2, 0, 1.75).translate(-0.018, 1.553, 0), PpPart.Body, 0, C.hair, PpMask.Fixed),   // tóc (chỏm cầu, lệch ra sau)
38	    ppTag(new THREE.ConeGeometry(0.31, 0.17, 10).translate(0, 1.7, 0), PpPart.Hat, 0, C.hat, PpMask.Fixed),                      // nón lá
39	    ppTag(new THREE.BoxGeometry(0.13, 0.32, 0.25).translate(-0.18, 1.17, 0), PpPart.Pack, 0, C.pack, PpMask.Fixed)               // ba lô sau lưng (−X)
40	  ];
