    const S = this.ship;
    if (S.z !== S.target) {
      const step = S.speed * dt * ctrl.speed * Math.sign(S.target - S.z);
      S.z = Math.abs(S.target - S.z) <= Math.abs(step) ? S.target : S.z + step;
      S.obj.position.z = S.z; S.obj.rotation.y = S.target > 0 ? 0 : Math.PI;
    }
